    private String breadcrumb = "AEROCARE  /  Dashboard";
    private String nama = "Humaira";
    private String peran = "Admin";

    public String getBreadcrumb() {
        return breadcrumb;
    }

    public void setBreadcrumb(String breadcrumb) {
        this.breadcrumb = breadcrumb;
        lblBreadcrumb.setText(breadcrumb);
    }

    public String getNama() {
        return nama;
    }

    public void setNama(String nama) {
        this.nama = nama;
        lblNama.setText(nama);
        lblAvatar.setText(nama.isEmpty() ? "" : nama.substring(0, 1).toUpperCase());
    }

    /** Peran: Admin, Supervisor atau Petugas (menentukan warna avatar). */
    public String getPeran() {
        return peran;
    }

    public void setPeran(String peran) {
        this.peran = peran;
        lblPeran.setText(peran);
        String warna = "2563EB";
        if ("Supervisor".equalsIgnoreCase(peran)) {
            warna = "7C3AED";
        } else if ("Petugas".equalsIgnoreCase(peran)) {
            warna = "EA580C";
        }
        lblAvatar.setBackground(java.awt.Color.decode("#" + warna));
    }

